public class DOMNodePointer_findEnclosingAttribute_TriageGen2Test {

    /**
     * Helper method to access the protected static method via reflection.
     */
    @SuppressWarnings("unchecked")
    private String invokeFindEnclosingAttribute(Node n, String attrName) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("findEnclosingAttribute", Node.class, String.class);
        method.setAccessible(true);
        return (String) method.invoke(null, n, attrName);
    }

    @Test
    public void testFindEnclosingAttribute_NullNode() throws Exception {
        assertNull(invokeFindEnclosingAttribute(null, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_NonElementNode() throws Exception {
        Node textNode = mock(Node.class);
        Node parent = mock(Node.class);

        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(parent);
        when(parent.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(parent.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(textNode, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_ElementWithEmptyAttribute() throws Exception {
        Node child = mock(Element.class);
        Node parent = mock(Element.class);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("testAttr")).thenReturn(""); // Empty string case
        when(child.getParentNode()).thenReturn(parent);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("testAttr")).thenReturn("foundValue");
        when(parent.getParentNode()).thenReturn(null);

        assertEquals("foundValue", invokeFindEnclosingAttribute(child, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_ElementWithNullAttribute() throws Exception {
        Node child = mock(Element.class);
        Node parent = mock(Element.class);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("testAttr")).thenReturn(null); // Null case
        when(child.getParentNode()).thenReturn(parent);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("testAttr")).thenReturn("foundValue");
        when(parent.getParentNode()).thenReturn(null);

        assertEquals("foundValue", invokeFindEnclosingAttribute(child, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_SuccessAtCurrentNode() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("target")).thenReturn("targetValue");

        assertEquals("targetValue", invokeFindEnclosingAttribute(element, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_SuccessAtParentNode() throws Exception {
        Element child = mock(Element.class);
        Element parent = mock(Element.class);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("target")).thenReturn(""); // Should skip
        when(child.getParentNode()).thenReturn(parent);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("parentValue");
        when(parent.getParentNode()).thenReturn(null);

        assertEquals("parentValue", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_SuccessAtGrandparentNode() throws Exception {
        Element child = mock(Element.class);
        Node middle = mock(Node.class);
        Element grandparent = mock(Element.class);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("target")).thenReturn("");
        when(child.getParentNode()).thenReturn(middle);

        when(middle.getNodeType()).thenReturn(Node.TEXT_NODE); // Skip non-element
        when(middle.getParentNode()).thenReturn(grandparent);

        when(grandparent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(grandparent.getAttribute("target")).thenReturn("grandparentValue");
        when(grandparent.getParentNode()).thenReturn(null);

        assertEquals("grandparentValue", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_NoAttributeFoundInHierarchy() throws Exception {
        Element element = mock(Element.class);
        Node parent = mock(Node.class);

        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("target")).thenReturn("");
        when(element.getParentNode()).thenReturn(parent);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("");
        when(parent.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(element, "target"));
    }
}
